export function projectMaharashtraCoordinates(coordinates: [number, number]): [number, number] {
  const [longitude, latitude] = coordinates;
  return [
    PROJECTION.offsetX + (longitude * PROJECTION.xFactor - PROJECTION.minX) * PROJECTION.scale,
    PROJECTION.offsetY + (PROJECTION.maxLatitude - latitude) * PROJECTION.scale,
  ];
}

